from lxml import etree

_nsmap = {None: "raml21.xsd"}


class ScfInformationProvider:
    def __init__(self, scf_content):
        self._root = etree.fromstring(scf_content)

    def get_nr_cell_dist_names(self):
        return tuple(
            managed_object.get("distName")
            for managed_object in self._root.findall(".//managedObject[@class='com.nokia.srbts.nrbts:NRCELL']", _nsmap))

    def get_mplane_ip_address(self):
        try:
            managed_object = self._root.find(".//managedObject[@class='com.nokia.srbts.mnl:MPLANENW']", _nsmap)
            dist_name = managed_object.find("p[@name='mPlaneIpv4AddressDN']", _nsmap).text
            managed_object = self._root.find(f".//managedObject[@distName='{dist_name}']", _nsmap)
            mplane_ip_addr = managed_object.find("p[@name='localIpAddr']", _nsmap).text
        except AttributeError:
            list_ = self._root.find(".//list[@name='discoveredMplane']", _nsmap)
            dist_name = list_.find(".//p[@name='ipV4AddressDN1']", _nsmap).text
            managed_object = self._root.find(f".//managedObject[@distName='{dist_name}']", _nsmap)
            mplane_ip_addr = managed_object.find("p[@name='localIpAddrAllocated']", _nsmap).text
        return mplane_ip_addr
